// Normalize Remote OK jobs
// remoteok returns an array; first element is a metadata object, skip it
const raw = $input.first().json;
const jobs = Array.isArray(raw) ? raw : [];

const keywords = [
  'async remote','asynchronous remote','worldwide remote','global remote',
  'work from anywhere','remote data analyst','remote data scientist',
  'remote ai marketing','remote marketing analyst','remote growth analyst',
  'remote bi analyst','remote automation','remote ai workflow'
];

return jobs
  .filter(j => j && j.position) // skip metadata object
  .filter(j => {
    const text = (j.position + ' ' + (j.description || '') + ' ' + (j.tags || []).join(' ')).toLowerCase();
    return keywords.some(kw => text.includes(kw));
  })
  .map(j => ({
    json: {
      job_title: j.position || '',
      company: j.company || '',
      job_url: j.url || `https://remoteok.com/jobs/${j.id}`,
      source: 'Remote OK',
      location_text: j.location || 'Worldwide',
      salary: j.salary || '',
      description: (j.description || '').replace(/<[^>]*>/g, ' ').substring(0, 3000),
      posted_date: j.date || new Date().toISOString(),
      tags: (j.tags || []).join(', '),
      job_id: `remoteok_${j.id || j.slug}`
    }
  }));

// Normalize Remotive jobs
const raw = $input.first().json;
const jobs = raw.jobs || [];

const keywords = [
  'async remote','asynchronous remote','worldwide remote','global remote',
  'work from anywhere','data analyst','data scientist','marketing analyst',
  'growth analyst','bi analyst','automation','ai marketing','ai workflow'
];

return jobs
  .filter(j => {
    const text = (j.title + ' ' + j.description + ' ' + (j.candidate_required_location || '')).toLowerCase();
    return keywords.some(kw => text.includes(kw));
  })
  .map(j => ({
    json: {
      job_title: j.title || '',
      company: j.company_name || '',
      job_url: j.url || '',
      source: 'Remotive',
      location_text: j.candidate_required_location || 'Worldwide',
      salary: j.salary || '',
      description: (j.description || '').replace(/<[^>]*>/g, ' ').substring(0, 3000),
      posted_date: j.publication_date || new Date().toISOString(),
      tags: (j.tags || []).join(', '),
      job_id: `remotive_${j.id}`
    }
  }));

// Normalize We Work Remotely RSS items
const items = $input.all();
const keywords = [
  'async','remote','worldwide','global','anywhere','data analyst',
  'data scientist','marketing analyst','growth','bi analyst','automation','ai'
];

return items
  .filter(item => {
    const text = ((item.json.title || '') + ' ' + (item.json.contentSnippet || '') + ' ' + (item.json.content || '')).toLowerCase();
    return keywords.some(kw => text.includes(kw));
  })
  .map(item => ({
    json: {
      job_title: item.json.title || '',
      company: (item.json.title || '').split(' at ').pop() || '',
      job_url: item.json.link || item.json.guid || '',
      source: 'We Work Remotely',
      location_text: 'Worldwide',
      salary: '',
      description: (item.json.contentSnippet || item.json.content || '').replace(/<[^>]*>/g, ' ').substring(0, 3000),
      posted_date: item.json.pubDate || new Date().toISOString(),
      tags: '',
      job_id: `wwr_${Buffer.from(item.json.link || item.json.guid || Math.random().toString()).toString('base64').substring(0, 16)}`
    }
  }));

// Normalize Himalayas jobs
const raw = $input.first().json;
const jobs = raw.jobs || raw.data || raw || [];
const jobArray = Array.isArray(jobs) ? jobs : [];

const keywords = [
  'async','worldwide','global','anywhere','data analyst','data scientist',
  'marketing analyst','growth analyst','bi analyst','automation','ai marketing'
];

return jobArray
  .filter(j => {
    const text = ((j.title || '') + ' ' + (j.description || '') + ' ' + (j.locationRestrictions || '')).toLowerCase();
    return keywords.some(kw => text.includes(kw));
  })
  .map(j => ({
    json: {
      job_title: j.title || '',
      company: (j.company && j.company.name) || j.companyName || '',
      job_url: j.applicationLink || j.url || `https://himalayas.app/jobs/${j.slug || j.id}`,
      source: 'Himalayas',
      location_text: j.locationRestrictions || 'Worldwide',
      salary: j.salary || (j.salaryMin ? `${j.salaryMin}-${j.salaryMax} ${j.salaryCurrency || 'USD'}` : ''),
      description: (j.description || '').replace(/<[^>]*>/g, ' ').substring(0, 3000),
      posted_date: j.publishedAt || j.createdAt || new Date().toISOString(),
      tags: (j.skills || []).map(s => s.name || s).join(', '),
      job_id: `himalayas_${j.id || j.slug}`
    }
  }));

// Normalize Dynamite Jobs RSS items
const items = $input.all();
const keywords = [
  'async','remote','worldwide','global','anywhere','data','marketing',
  'analyst','growth','automation','ai'
];

return items
  .filter(item => {
    const text = ((item.json.title || '') + ' ' + (item.json.contentSnippet || '') + ' ' + (item.json.content || '')).toLowerCase();
    return keywords.some(kw => text.includes(kw));
  })
  .map(item => ({
    json: {
      job_title: item.json.title || '',
      company: (item.json['dc:creator'] || item.json.author || '').replace(/<[^>]*>/g, ''),
      job_url: item.json.link || item.json.guid || '',
      source: 'Dynamite Jobs',
      location_text: 'Remote',
      salary: '',
      description: (item.json.contentSnippet || item.json.content || '').replace(/<[^>]*>/g, ' ').substring(0, 3000),
      posted_date: item.json.pubDate || new Date().toISOString(),
      tags: '',
      job_id: `dynamite_${Buffer.from(item.json.link || Math.random().toString()).toString('base64').substring(0, 16)}`
    }
  }));

// Normalize Wellfound jobs
// Wellfound may block or return HTML — graceful fallback
try {
  const raw = $input.first().json;
  const edges = (raw.data && raw.data.jobListings && raw.data.jobListings.edges) || [];
  return edges.map(({ node: j }) => ({
    json: {
      job_title: j.title || '',
      company: (j.company && j.company.name) || '',
      job_url: j.url || '',
      source: 'Wellfound',
      location_text: 'Remote',
      salary: j.compensation ? `${j.compensation.minValue || ''}-${j.compensation.maxValue || ''} ${j.compensation.currency || 'USD'}` : '',
      description: (j.description || '').replace(/<[^>]*>/g, ' ').substring(0, 3000),
      posted_date: new Date().toISOString(),
      tags: (j.skills || []).map(s => s.displayName).join(', '),
      job_id: `wellfound_${j.id}`
    }
  }));
} catch(e) {
  return []; // graceful skip if Wellfound is unavailable
}

// Normalize YC Work at a Startup jobs
try {
  const raw = $input.first().json;
  const jobs = raw.jobs || raw.startups || raw || [];
  const jobArray = Array.isArray(jobs) ? jobs : [];
  return jobArray.map(j => ({
    json: {
      job_title: j.title || j.role || '',
      company: j.company || j.startup || j.name || '',
      job_url: j.url || j.apply_url || `https://www.workatastartup.com/jobs/${j.id}`,
      source: 'YC Work at a Startup',
      location_text: j.location || 'Remote',
      salary: j.salary || '',
      description: (j.description || '').replace(/<[^>]*>/g, ' ').substring(0, 3000),
      posted_date: j.created_at || new Date().toISOString(),
      tags: (j.skills || j.tags || []).join(', '),
      job_id: `yc_${j.id}`
    }
  }));
} catch(e) {
  return [];
}

// Normalize Otta jobs
try {
  const raw = $input.first().json;
  const jobs = raw.jobs || raw.data || raw || [];
  const jobArray = Array.isArray(jobs) ? jobs : [];
  return jobArray.map(j => ({
    json: {
      job_title: j.title || '',
      company: (j.company && j.company.name) || j.company_name || '',
      job_url: j.url || j.apply_url || `https://otta.com/jobs/${j.id || j.slug}`,
      source: 'Otta',
      location_text: j.remote ? 'Remote' : (j.location || ''),
      salary: j.salary || '',
      description: (j.description || '').replace(/<[^>]*>/g, ' ').substring(0, 3000),
      posted_date: j.posted_at || new Date().toISOString(),
      tags: (j.skills || j.tags || []).join(', '),
      job_id: `otta_${j.id || j.slug}`
    }
  }));
} catch(e) {
  return [];
}

// Deduplicate: skip jobs already in Google Sheets
// Input 0: new jobs (from Merge 7)
// Input 1: existing rows from Google Sheets

const newJobs = $input.all();
const existingSheet = $('Get Existing URLs').all();

const existingUrls = new Set(existingSheet.map(r => (r.json.job_url || '').trim().toLowerCase()));
const existingKeys = new Set(existingSheet.map(r => `${(r.json.company || '').toLowerCase()}|${(r.json.job_title || '').toLowerCase()}`));

const today = new Date().toISOString().split('T')[0];

const unique = [];
const seen = new Set();

for (const item of newJobs) {
  const url = (item.json.job_url || '').trim().toLowerCase();
  const key = `${(item.json.company || '').toLowerCase()}|${(item.json.job_title || '').toLowerCase()}`;

  if (!url || existingUrls.has(url) || existingKeys.has(key) || seen.has(url)) continue;
  seen.add(url);

  unique.push({ json: { ...item.json, date_found: today } });
}

return unique;

// Taiwan Eligibility Hard Filter
// Reject jobs that explicitly exclude Taiwan-based workers

const rejectPatterns = [
  /\bus only\b/i, /\busa only\b/i, /\bunited states only\b/i,
  /\bcanada only\b/i, /\buk only\b/i, /\bunited kingdom only\b/i,
  /\beu only\b/i, /\beurope only\b/i, /\beuropean union only\b/i,
  /\baustralia only\b/i, /\baus only\b/i,
  /\bmust be based in\b/i, /\bmust live in\b/i, /\bmust reside in\b/i,
  /\bmust be authorized to work in\b/i,
  /\blocal work permit required\b/i, /\bwork permit required\b/i,
  /\bhybrid\b/i, /\bonsite\b/i, /\bon-site\b/i, /\bin-office\b/i,
  /\boffice required\b/i, /\bin office\b/i,
  /\bremote within (the )?(us|uk|eu|canada|australia)\b/i,
  /\bcountry only\b/i,
  /\bfixed (us|est|pst|cet) hours\b/i,
  /\bmust work us hours\b/i, /\bmust overlap.*\bus\b/i,
  /\bno international\b/i, /\bdomestic only\b/i
];

const keepPatterns = [
  /worldwide remote/i, /global remote/i, /work from anywhere/i,
  /\banywhere\b/i, /\bapac\b/i, /international contractors/i,
  /contractor role/i, /\bb2b\b.*contractor/i, /hires via deel/i,
  /hires via remote\.com/i, /hires via oyster/i, /\beor\b/i,
  /employer of record/i, /remote.?first/i, /distributed team/i,
  /all timezones/i, /any timezone/i, /async/i, /asynchronous/i
];

const results = { kept: [], rejected: [] };

for (const item of $input.all()) {
  const text = [
    item.json.job_title, item.json.location_text,
    item.json.description, item.json.tags
  ].join(' ');

  const hasKeepSignal = keepPatterns.some(p => p.test(text));
  const hasRejectSignal = rejectPatterns.some(p => p.test(text));

  if (hasRejectSignal && !hasKeepSignal) {
    results.rejected.push({ json: { ...item.json, rejection_reason: 'hard_filter_country_restriction' } });
  } else {
    results.kept.push({ json: { ...item.json, hard_filter_passed: true, has_keep_signal: hasKeepSignal } });
  }
}

// Store rejected count in workflow static data for digest
const staticData = $getWorkflowStaticData('global');
staticData.hard_filter_rejected = results.rejected.length;
staticData.hard_filter_kept = results.kept.length;

return results.kept;

// Parse Claude AI response + run Async Filter + Role Fit + Scoring
// Merge the AI result back with the original job data from previous batch item

const aiResponse = $input.first().json;
const originalJob = $('Split Into Batches').first().json;

// Parse AI JSON from Claude response
let aiResult = {};
try {
  const content = aiResponse.content && aiResponse.content[0] && aiResponse.content[0].text;
  aiResult = JSON.parse(content || '{}');
} catch(e) {
  aiResult = { taiwan_eligible: 'unclear', reason: 'parse error', location_risk: 'medium', timezone_risk: 'medium', contractor_possible: 'unclear', decision: 'manual_check' };
}

const text = (originalJob.description + ' ' + originalJob.job_title + ' ' + originalJob.location_text + ' ' + originalJob.tags).toLowerCase();

// --- ASYNC FILTER ---
const asyncHighSignals = ['async','asynchronous','flexible hours','flexible schedule','no meeting','low meeting'];
const asyncMedSignals = ['distributed team','remote first','work across time zones','any timezone','your own schedule'];
const asyncRejectSignals = ['strict 9 to 5','9-5','fixed us hours','fixed est','fixed pst','fixed cet','daily standup required','must overlap full business day','daily live calls required'];

const hasAsyncHigh = asyncHighSignals.some(s => text.includes(s));
const hasAsyncMed = asyncMedSignals.some(s => text.includes(s));
const hasAsyncReject = asyncRejectSignals.some(s => text.includes(s));

let async_level = 'low';
if (hasAsyncHigh) async_level = 'high';
else if (hasAsyncMed) async_level = 'medium';

// Reject if strong async rejection signal and NOT explicitly async
if (hasAsyncReject && !hasAsyncHigh) {
  return [{
    json: {
      ...originalJob, ...aiResult,
      async_level: 'rejected',
      rejection_reason: 'fixed_timezone_hours',
      decision: 'reject'
    }
  }];
}

// --- ROLE FIT FILTER ---
const primaryRoles = [
  'data analyst','data scientist','junior data scientist','business intelligence',
  'bi analyst','marketing analyst','performance marketing','growth analyst',
  'ai marketing','ai automation','ai workflow','martech','creative strategist'
];
const adjacentRoles = [
  'analyst','data','marketing','growth','automation','reporting',
  'insights','metrics','tableau','power bi','sql','python'
];

const isPrimaryRole = primaryRoles.some(r => text.includes(r));
const isAdjacentRole = !isPrimaryRole && adjacentRoles.some(r => text.includes(r));

let role_category = 'other';
if (isPrimaryRole) role_category = 'primary';
else if (isAdjacentRole) role_category = 'adjacent';

// --- SCORING ---
let score = 0;

// Taiwan eligibility (40 pts max)
const eligible = aiResult.taiwan_eligible || 'unclear';
const locRisk = aiResult.location_risk || 'medium';
if (eligible === 'yes' && locRisk === 'low') score += 40;
else if (eligible === 'yes') score += 35;
else if (text.match(/apac/i)) score += 30;
else if (eligible === 'unclear') score += 20;
else score += 0;

// Check for strong worldwide signals
if (text.match(/worldwide remote|work from anywhere|global remote|hire.*anywhere|international contractor/i)) score = Math.max(score, 35);

// Async fit (25 pts max)
if (async_level === 'high') score += 25;
else if (text.match(/flexible hours|flexible schedule/i)) score += 20;
else if (async_level === 'medium') score += 15;
else if (text.match(/remote.?first|distributed team/i)) score += 10;

// Role fit (25 pts max)
if (isPrimaryRole) score += 25;
else if (isAdjacentRole) score += 15;

// Salary fit (25 pts max)
const salaryText = (originalJob.salary || '').toLowerCase();
let salaryPts = 0;
if (salaryText) {
  const nums = salaryText.match(/\d[\d,]+/g) || [];
  const maxNum = Math.max(...nums.map(n => parseInt(n.replace(/,/g, ''))));
  if (!isNaN(maxNum)) {
    // Convert to monthly if looks like annual
    const monthly = maxNum > 10000 ? maxNum / 12 : maxNum;
    if (monthly >= 5000) salaryPts = 25;
    else if (monthly >= 3000) salaryPts = 15;
    else salaryPts = 10;
  } else {
    salaryPts = 10; // salary listed but can't parse
  }
}
score += salaryPts;

// Cap at 100
score = Math.min(score, 100);

// --- WHY GOOD FIT ---
const whyParts = [];
if (eligible === 'yes') whyParts.push('Taiwan-eligible');
if (async_level === 'high') whyParts.push('fully async');
if (isPrimaryRole) whyParts.push('direct role match');
if (salaryPts >= 15) whyParts.push('good salary');
if (aiResult.contractor_possible === 'yes') whyParts.push('contractor-friendly');
const why_good_fit = whyParts.join(', ') || 'Needs manual review';

// Determine final decision
let decision = aiResult.decision || 'manual_check';
if (eligible === 'no' || locRisk === 'high') decision = 'reject';
if (score < 70) decision = score < 50 ? 'reject' : 'manual_check';
if (eligible === 'yes' && score >= 85 && async_level !== 'low' && locRisk === 'low') decision = 'apply';

return [{
  json: {
    ...originalJob,
    taiwan_eligible: aiResult.taiwan_eligible || 'unclear',
    taiwan_reason: aiResult.reason || '',
    location_risk: aiResult.location_risk || 'medium',
    timezone_risk: aiResult.timezone_risk || 'medium',
    contractor_possible: aiResult.contractor_possible || 'unclear',
    async_level,
    role_category,
    score,
    why_good_fit,
    decision,
    application_status: decision === 'apply' ? 'ready_to_apply' : 'pending_review',
    notes: ''
  }
}];

// Attach cover letter text to the job data and pass forward
const coverResponse = $input.first().json;
const jobData = $('Score >= 85?').first().json;

let coverLetter = '';
try {
  coverLetter = coverResponse.content && coverResponse.content[0] && coverResponse.content[0].text || '';
} catch(e) {
  coverLetter = 'Cover letter generation failed.';
}

return [{ json: { ...jobData, cover_letter_draft: coverLetter } }];

