// Build daily digest message
const jobs = $input.all().map(i => i.json);

if (!jobs.length) {
  return [{ json: { digest: 'No Taiwan-eligible async jobs found today. Check tomorrow!', subject: 'Daily Job Hunt — No new matches today' } }];
}

// Sort by score desc
jobs.sort((a, b) => Number(b.score) - Number(a.score));

const topJobs = jobs.filter(j => j.decision !== 'reject').slice(0, 10);
const manualCheck = jobs.filter(j => j.taiwan_eligible === 'unclear' && Number(j.score) >= 70);

// Rejection stats from static data
const staticData = $getWorkflowStaticData('global');
const hardRejected = staticData.hard_filter_rejected || 0;

let msg = `📋 DAILY TAIWAN ELIGIBLE ASYNC REMOTE JOBS\n${'='.repeat(45)}\n`;
msg += `Date: ${new Date().toLocaleDateString('en-US', { timeZone: 'Asia/Taipei', weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}\n`;
msg += `Total new jobs today: ${jobs.length} | Passed filter: ${topJobs.length}\n\n`;

if (topJobs.length) {
  msg += `🎯 TOP JOBS TODAY\n${'-'.repeat(35)}\n\n`;
  topJobs.forEach((j, i) => {
    msg += `${i + 1}. ${j.job_title}\n`;
    msg += `   Company: ${j.company}\n`;
    msg += `   Score: ${j.score}/100\n`;
    msg += `   Taiwan eligible: ${j.taiwan_eligible} — ${j.taiwan_reason}\n`;
    msg += `   Async level: ${j.async_level}\n`;
    msg += `   Timezone risk: ${j.timezone_risk}\n`;
    msg += `   Salary: ${j.salary || 'Not listed'}\n`;
    msg += `   Why it fits Jerry: ${j.why_good_fit}\n`;
    msg += `   Apply: ${j.job_url}\n\n`;
  });
} else {
  msg += `No high-confidence matches today.\n\n`;
}

if (manualCheck.length) {
  msg += `🔍 MANUAL CHECK NEEDED (Taiwan unclear, score >= 70)\n${'-'.repeat(35)}\n`;
  manualCheck.forEach(j => {
    msg += `• ${j.job_title} @ ${j.company} (score: ${j.score}) — ${j.taiwan_reason}\n  ${j.job_url}\n`;
  });
  msg += '\n';
}

msg += `❌ REJECTED SUMMARY\n${'-'.repeat(35)}\n`;
msg += `Hard filter (country/hybrid/onsite): ${hardRejected}\n`;
msg += `Low score (< 70): ${jobs.filter(j => Number(j.score) < 70).length}\n`;
msg += `AI rejected (Taiwan ineligible): ${jobs.filter(j => j.taiwan_eligible === 'no').length}\n\n`;

msg += `View all in Google Sheets → Taiwan Eligible Async Remote Jobs\n`;

return [{ json: { digest: msg, subject: `Daily Job Hunt — ${topJobs.length} match${topJobs.length !== 1 ? 'es' : ''} (${new Date().toLocaleDateString('en-US', { timeZone: 'Asia/Taipei' })})` } }];
